#include <algorithm>
#include <mutex>
#include <unordered_map>
#include <vector>

// One registry per stream, PARTITIONED BY INSTANCE: a stream belongs to
// the Hybrid<Class> that emits it, so a subscriber on one instance never
// receives another instance's events (the ports used to be global, so
// every subscriber saw every instance). Every concurrent Dart subscriber
// registers its own ReceivePort. Guarded by a mutex — register/release
// run on the Dart isolate thread while emits may come from any thread.
struct _NitroStreamPorts {
    std::mutex mtx;
    std::unordered_map<const void*, std::vector<int64_t>> byInstance;
    void add(const void* inst, int64_t p) {
        std::lock_guard<std::mutex> l(mtx); byInstance[inst].push_back(p);
    }
    // Release carries only the port: Dart cancels a subscription without
    // naming the instance, so drop it wherever it is registered.
    void remove(int64_t p) {
        std::lock_guard<std::mutex> l(mtx);
        for (auto& kv : byInstance) {
            auto& v = kv.second;
            v.erase(std::remove(v.begin(), v.end(), p), v.end());
        }
    }
    void dropInstance(const void* inst) {
        std::lock_guard<std::mutex> l(mtx); byInstance.erase(inst);
    }
    std::vector<int64_t> snapshot(const void* inst) {
        std::lock_guard<std::mutex> l(mtx);
        auto it = byInstance.find(inst);
        return it == byInstance.end() ? std::vector<int64_t>() : it->second;
    }
};
static _NitroStreamPorts g_ports_stateChanges;
static _NitroStreamPorts g_ports_glassCapsulePresses;

// Called by destroy_instance so a disposed instance leaves no subscribers.
void _nitro_release_instance_streams(const void* impl) {
    g_ports_stateChanges.dropInstance(impl);
    g_ports_glassCapsulePresses.dropInstance(impl);
}

void HybridNitroFoldDuo::emit_stateChanges(NitroCppBuffer item) {
    auto _ports = g_ports_stateChanges.snapshot(this);
    if (_ports.empty()) { if (item.data) { free((void*)item.data); } return; }
    Dart_CObject obj;
    if (item.data == nullptr) {
        obj.type = Dart_CObject_kNull;
        for (int64_t _port : _ports) {
            if (!Dart_PostCObject_DL(_port, &obj)) { g_ports_stateChanges.remove(_port); }
        }
        return;
    }
    for (int64_t _port : _ports) {
        uint8_t* _copy = (uint8_t*)malloc(item.size);
        if (!_copy) { break; }
        memcpy(_copy, item.data, item.size);
        obj.type = Dart_CObject_kInt64;
        obj.value.as_int64 = (intptr_t)_copy;
        if (!Dart_PostCObject_DL(_port, &obj)) {
            free(_copy);
            g_ports_stateChanges.remove(_port);
        }
    }
    free((void*)item.data);
}

void HybridNitroFoldDuo::emit_glassCapsulePresses(NitroCppBuffer item) {
    auto _ports = g_ports_glassCapsulePresses.snapshot(this);
    if (_ports.empty()) { if (item.data) { free((void*)item.data); } return; }
    Dart_CObject obj;
    if (item.data == nullptr) {
        obj.type = Dart_CObject_kNull;
        for (int64_t _port : _ports) {
            if (!Dart_PostCObject_DL(_port, &obj)) { g_ports_glassCapsulePresses.remove(_port); }
        }
        return;
    }
    for (int64_t _port : _ports) {
        uint8_t* _copy = (uint8_t*)malloc(item.size);
        if (!_copy) { break; }
        memcpy(_copy, item.data, item.size);
        obj.type = Dart_CObject_kInt64;
        obj.value.as_int64 = (intptr_t)_copy;
        if (!Dart_PostCObject_DL(_port, &obj)) {
            free(_copy);
            g_ports_glassCapsulePresses.remove(_port);
        }
    }
    free((void*)item.data);
}

static void _nitro_desktop_err(NitroError* _out, const char* _name, const char* _message) {
    nitro_report_error(_name, _message, nullptr, nullptr);
    if (_out) {
        _out->hasError = 1;
        _out->name = _name ? strdup(_name) : nullptr;
        _out->message = _message ? strdup(_message) : nullptr;
        _out->code = nullptr;
        _out->stackTrace = nullptr;
    }
}

#include <atomic>
#include <memory>
#include <mutex>
#include <unordered_map>

using HybridNitroFoldDuoFactory = std::function<std::shared_ptr<HybridNitroFoldDuo>(const std::string&)>;
static std::unordered_map<int64_t, std::shared_ptr<HybridNitroFoldDuo>>& _g_instances() {
    static std::unordered_map<int64_t, std::shared_ptr<HybridNitroFoldDuo>> m;
    return m;
}
static std::mutex& _g_instances_mtx() {
    static std::mutex m;
    return m;
}
static std::atomic<int64_t>& _g_next_instance_id() {
    static std::atomic<int64_t> id{1};
    return id;
}
static HybridNitroFoldDuoFactory& _g_factory() {
    static HybridNitroFoldDuoFactory f;
    return f;
}

static constexpr int _kNitroCacheWays = 8;
struct alignas(64) _NitroInstSlot {
    std::atomic<int64_t> id{-1};
    std::atomic<HybridNitroFoldDuo*> ptr{nullptr};
};
static _NitroInstSlot _g_inst_cache[_kNitroCacheWays];
static HybridNitroFoldDuo* _nitro_get_instance(int64_t id) {
    _NitroInstSlot& _slot = _g_inst_cache[(uint64_t)id & (_kNitroCacheWays - 1)];
    if (_slot.id.load(std::memory_order_acquire) == id) {
        return _slot.ptr.load(std::memory_order_relaxed);
    }
    std::lock_guard<std::mutex> _lk(_g_instances_mtx());
    auto it = _g_instances().find(id);
    HybridNitroFoldDuo* p = (it != _g_instances().end()) ? it->second.get() : nullptr;
    if (p) {
        _slot.ptr.store(p, std::memory_order_relaxed);
        _slot.id.store(id, std::memory_order_release);
    }
    return p;
}
static void _nitro_invalidate_cache() {
    for (int _i = 0; _i < _kNitroCacheWays; ++_i) {
        _g_inst_cache[_i].id.store(-1, std::memory_order_release);
        _g_inst_cache[_i].ptr.store(nullptr, std::memory_order_relaxed);
    }
}

// Defined with the stream registries below (which may be emitted after
// this block): drops every subscriber belonging to one instance.
void _nitro_release_instance_streams(const void* impl);

extern "C" {
void nitro_fold_duo_register_factory(void* fn) {
    _g_factory() = *static_cast<HybridNitroFoldDuoFactory*>(fn);
}
void nitro_fold_duo_register_impl(HybridNitroFoldDuo* impl) {
    std::lock_guard<std::mutex> _lk(_g_instances_mtx());
    if (impl) _g_instances()[0] = std::shared_ptr<HybridNitroFoldDuo>(impl, [](HybridNitroFoldDuo*){});
    else _g_instances().erase(0);
    _nitro_invalidate_cache();
}
HybridNitroFoldDuo* nitro_fold_duo_get_impl() {
    return _nitro_get_instance(0);
}
NITRO_EXPORT int64_t nitro_fold_duo_create_instance(const char* key) {
    if (_g_factory()) {
        auto inst = _g_factory()(key ? key : "");
        if (!inst) return -1;
        std::lock_guard<std::mutex> _lk(_g_instances_mtx());
        int64_t id = ++_g_next_instance_id();
        _g_instances()[id] = std::move(inst);
        return id;
    }
      // Legacy: no factory registered — return 0 (single global impl slot)
    return 0;
}
NITRO_EXPORT void nitro_fold_duo_destroy_instance(int64_t instanceId) {
    // Slot 0 belongs to register_impl (the legacy single impl and the
    // stream-emitter target), never to a Dart instance. Without this a
    // plugin that registers no factory hands every instance id 0, and the
    // first dispose() erases the slot for all of them.
    if (instanceId == 0) { return; }
    std::lock_guard<std::mutex> _lk(_g_instances_mtx());
    auto _it = _g_instances().find(instanceId);
    if (_it != _g_instances().end()) {
        _nitro_release_instance_streams(_it->second.get());
    }
    _g_instances().erase(instanceId);
    _nitro_invalidate_cache();
}
NITRO_EXPORT void nitro_fold_duo_nitro_free(void* ptr) { if (ptr) { free(ptr); } }
NITRO_EXPORT void* nitro_fold_duo_nitro_alloc(size_t size) { return malloc(size); }

void* nitro_fold_duo_current_state(int64_t instanceId, NitroError* _nitro_err) {
    nitro_fold_duo_clear_error();
    if (_nitro_err) { _nitro_err->hasError = 0; }  // S8: clear slot
    auto _impl = _nitro_get_instance(instanceId);
    if (!_impl) { _nitro_desktop_err(_nitro_err, "NotInitialized", "No C++ implementation registered. Call nitro_fold_duo_register_impl() first."); return nullptr; }
    try {
        NitroCppBuffer _res = _impl->currentState();
        return (void*)_res.data;
    } catch (const std::exception& e) {
        _nitro_desktop_err(_nitro_err, "CppException", e.what());
        return nullptr;
    } catch (...) {
        _nitro_desktop_err(_nitro_err, "CppException", "Unknown C++ exception");
        return nullptr;
    }
}

