    if (!_impl) { _nitro_desktop_err(_nitro_err, "NotInitialized", "No C++ implementation registered. Call nitro_fold_duo_register_impl() first."); return; }
    try {
        NitroCppBuffer _buf_symbols = { (const uint8_t*)symbols + 4, (size_t)*(int32_t*)symbols };
        NitroCppBuffer _buf_titles = { (const uint8_t*)titles + 4, (size_t)*(int32_t*)titles };
